/**
 * Lightweight Vendored Canvas Chart Engine for MailCheck
 * Implements line, bar, and doughnut charts with zero external dependencies.
 */
(function(global) {
  class Chart {
    constructor(ctx, config) {
      this.canvas = typeof ctx === 'string' ? document.getElementById(ctx) : ctx;
      if (!this.canvas) return;
      this.ctx = this.canvas.getContext('2d');
      this.config = config || {};
      this.data = config.data || { labels: [], datasets: [] };
      this.type = config.type || 'line';
      this.options = config.options || {};
      this.render();

      window.addEventListener('resize', () => this.render());
    }

    destroy() {
      // Cleanup if needed
    }

    update() {
      this.render();
    }

    render() {
      if (!this.canvas || !this.ctx) return;
      const ctx = this.ctx;
      const rect = this.canvas.getBoundingClientRect();
      const dpr = window.devicePixelRatio || 1;
      
      const width = rect.width || this.canvas.width || 600;
      const height = rect.height || this.canvas.height || 260;

      this.canvas.width = width * dpr;
      this.canvas.height = height * dpr;
      ctx.scale(dpr, dpr);

      ctx.clearRect(0, 0, width, height);

      if (this.type === 'doughnut') {
        this.renderDoughnut(width, height);
      } else {
        this.renderAxesAndData(width, height);
      }
    }

    renderAxesAndData(w, h) {
      const ctx = this.ctx;
      const padding = { top: 20, right: 20, bottom: 40, left: 45 };
      const chartW = w - padding.left - padding.right;
      const chartH = h - padding.top - padding.bottom;

      const labels = this.data.labels || [];
      const datasets = this.data.datasets || [];

      // Find max value
      let maxVal = 10;
      for (const ds of datasets) {
        for (const v of ds.data || []) {
          if (v > maxVal) maxVal = v;
        }
      }
      maxVal = Math.ceil(maxVal * 1.15);

      // Draw grid lines
      const gridSteps = 4;
      ctx.strokeStyle = '#f1f5f9';
      ctx.lineWidth = 1;
      ctx.font = '11px -apple-system, sans-serif';
      ctx.fillStyle = '#94a3b8';
      ctx.textAlign = 'right';

      for (let i = 0; i <= gridSteps; i++) {
        const yVal = Math.round((maxVal / gridSteps) * i);
        const yPos = padding.top + chartH - (i / gridSteps) * chartH;

        ctx.beginPath();
        ctx.moveTo(padding.left, yPos);
        ctx.lineTo(w - padding.right, yPos);
        ctx.stroke();

        ctx.fillText(String(yVal), padding.left - 8, yPos + 4);
      }

      // Draw X axis labels
      ctx.textAlign = 'center';
      const stepX = labels.length > 1 ? chartW / (labels.length - 1) : chartW / 2;
      for (let i = 0; i < labels.length; i++) {
        // Skip every other label if too crowded
        if (labels.length > 12 && i % 2 !== 0 && i !== labels.length - 1) continue;
        const xPos = padding.left + (labels.length > 1 ? i * stepX : chartW / 2);
        ctx.fillText(labels[i], xPos, h - 14);
      }

      // Draw Datasets
      for (const ds of datasets) {
        const color = ds.borderColor || ds.backgroundColor || '#3b82f6';
        const data = ds.data || [];

        ctx.strokeStyle = color;
        ctx.lineWidth = 2.5;
        ctx.lineJoin = 'round';
        ctx.lineCap = 'round';
        ctx.beginPath();

        const points = [];
        for (let i = 0; i < data.length; i++) {
          const val = data[i] || 0;
          const x = padding.left + (labels.length > 1 ? i * stepX : chartW / 2);
          const y = padding.top + chartH - (val / maxVal) * chartH;
          points.push({ x, y });

          if (i === 0) {
            ctx.moveTo(x, y);
          } else {
            ctx.lineTo(x, y);
          }
        }
        ctx.stroke();

        // Fill area under line if requested
        if (ds.fill) {
          ctx.lineTo(points[points.length - 1].x, padding.top + chartH);
          ctx.lineTo(points[0].x, padding.top + chartH);
          ctx.closePath();
          ctx.fillStyle = ds.backgroundColor || 'rgba(59, 130, 246, 0.08)';
          ctx.fill();
        }

        // Draw points
        ctx.fillStyle = '#ffffff';
        ctx.lineWidth = 2;
        for (const pt of points) {
          ctx.beginPath();
          ctx.arc(pt.x, pt.y, 3.5, 0, Math.PI * 2);
          ctx.fill();
          ctx.stroke();
        }
      }
    }

    renderDoughnut(w, h) {
      const ctx = this.ctx;
      const cx = w / 2;
      const cy = h / 2;
      const radius = Math.min(w, h) * 0.38;
      const innerRadius = radius * 0.65;

      const ds = (this.data.datasets || [])[0] || { data: [], backgroundColor: [] };
      const total = ds.data.reduce((a, b) => a + b, 0) || 1;

      let startAngle = -Math.PI / 2;
      for (let i = 0; i < ds.data.length; i++) {
        const sliceAngle = (ds.data[i] / total) * Math.PI * 2;
        const endAngle = startAngle + sliceAngle;

        ctx.beginPath();
        ctx.arc(cx, cy, radius, startAngle, endAngle);
        ctx.arc(cx, cy, innerRadius, endAngle, startAngle, true);
        ctx.closePath();
        ctx.fillStyle = (ds.backgroundColor && ds.backgroundColor[i]) || '#cbd5e1';
        ctx.fill();

        startAngle = endAngle;
      }
    }
  }

  global.Chart = Chart;
})(window);
